insert into public.products (
  brand_id, slug, title_zh_hk, title_zh_cn, title_en,
  description_zh_hk, description_zh_cn, description_en,
  price_hkd, stock, image_paths, status, sort
)
select b.id, x.slug, x.title_zh_hk, x.title_zh_cn, x.title_en,
  x.description_zh_hk, x.description_zh_cn, x.description_en,
  x.price_hkd, x.stock, x.image_paths, 'on_sale', x.sort
from jsonb_to_recordset($json$[{"brand_slug":"dermaquest","slug":"peptide-firming-eye-cream","title_zh_hk":"Peptide\u7dca\u819a\u773c\u971c","title_zh_cn":"Peptide\u7d27\u80a4\u773c\u971c","title_en":"Peptide Firming Eye Cream","description_zh_hk":"<p>\u9069\u5408\u6240\u6709\u808c\u819a</p>\n<p>\u5c08\u70ba\u8106\u5f31\u7684\u773c\u90e8\u808c\u819a\u800c\u8a2d\uff0c\u860a\u542b\u591a\u7a2e\u86cb\u767d\u80bd\u7cbe\u83ef\uff0c\u6709\u52a9\u91cd\u7d44\u9aa8\u81a0\u539f\u53ca\u5f48\u6027\u86cb\u767d\uff0c\u64ab\u5e73\u7d30\u7d0b\u53ca\u76ba\u7d0b\u3002\u7522\u54c1\u540c\u6642\u91dd\u5c0d\u9ed1\u773c\u5708\u53ca\u773c\u888b\u6d6e\u816b\u7b49\u554f\u984c\uff0c\u4f7f\u96d9\u773c\u56de\u5fa9\u660e\u4eae\u7dca\u7dfb\u3002</p>\n\n<p>\u4e3b\u8981\u529f\u6548</p>\n<p>\u2013 \u5f37\u6548\u6297\u6c27\u5316\u6210\u4efd\u4e2d\u548c\u81ea\u7531\u57fa\uff0c\u4fdd\u8b77\u808c\u819a\u7d30\u80de</p>\n<p>\u2013 \u91cd\u7d44\u808c\u819a\u7d30\u80de\uff0c\u4f7f\u808c\u819a\u7dca\u7dfb\u98fd\u6eff\uff0c\u9810\u9632\u53ca\u64ab\u5e73\u773c\u90e8\u76ba\u7d0b</p>\n<p>\u2013 \u4fdd\u8b77\u808c\u819a\u7684\u81a0\u539f\u86cb\u767d\u53ca\u5f48\u6027\u86cb\u767d</p>\n<p>\u2013 \u8212\u7de9\u773c\u888b\u6d6e\u816b</p>\n\n<p>\u4e3b\u8981\u6210\u4efd</p>\n<p>\u2013 \u74b0\u72c0\u56db\u80dc\u80bd</p>\n<p>\u2013 \u516d\u5143\u80dc\u80bd</p>\n<p>\u2013 \u4e94\u5143\u80dc\u80bd\u9178</p>\n<p>\u2013 \u56db\u80dc\u80bd\u68d5\u6ada\u9178\u8102</p>\n<p>\u2013 \u6c27\u5316\u7269\u9084\u539f\u9175\u7d20</p>\n<p>\u2013 \u900f\u660e\u8cea\u9178\u9209</p>","description_zh_cn":"<p>\u9002\u5408\u6240\u6709\u808c\u80a4</p>\n<p>\u4e13\u4e3a\u8106\u5f31\u7684\u773c\u90e8\u808c\u80a4\u800c\u8bbe\uff0c\u8574\u542b\u591a\u79cd\u86cb\u767d\u80bd\u7cbe\u534e\uff0c\u6709\u52a9\u91cd\u7ec4\u9aa8\u80f6\u539f\u53ca\u5f39\u6027\u86cb\u767d\uff0c\u629a\u5e73\u7ec6\u7eb9\u53ca\u76b1\u7eb9\u3002\u4ea7\u54c1\u540c\u65f6\u9488\u5bf9\u9ed1\u773c\u5708\u53ca\u773c\u888b\u6d6e\u80bf\u7b49\u95ee\u9898\uff0c\u4f7f\u53cc\u773c\u56de\u590d\u660e\u4eae\u7d27\u81f4\u3002</p>\n\n<p>\u4e3b\u8981\u529f\u6548</p>\n<p>\u2013 \u5f3a\u6548\u6297\u6c27\u5316\u6210\u4efd\u4e2d\u548c\u81ea\u7531\u57fa\uff0c\u4fdd\u62a4\u808c\u80a4\u7ec6\u80de</p>\n<p>\u2013 \u91cd\u7ec4\u808c\u80a4\u7ec6\u80de\uff0c\u4f7f\u808c\u80a4\u7d27\u81f4\u9971\u6ee1\uff0c\u9884\u9632\u53ca\u629a\u5e73\u773c\u90e8\u76b1\u7eb9</p>\n<p>\u2013 \u4fdd\u62a4\u808c\u80a4\u7684\u80f6\u539f\u86cb\u767d\u53ca\u5f39\u6027\u86cb\u767d</p>\n<p>\u2013 \u8212\u7f13\u773c\u888b\u6d6e\u80bf</p>\n\n<p>\u4e3b\u8981\u6210\u4efd</p>\n<p>\u2013 \u73af\u72b6\u56db\u80dc\u80bd</p>\n<p>\u2013 \u516d\u5143\u80dc\u80bd</p>\n<p>\u2013 \u4e94\u5143\u80dc\u80bd\u9178</p>\n<p>\u2013 \u56db\u80dc\u80bd\u68d5\u6988\u9178\u8102</p>\n<p>\u2013 \u6c27\u5316\u7269\u8fd8\u539f\u9175\u7d20</p>\n<p>\u2013 \u900f\u660e\u8d28\u9178\u94a0</p>","description_en":"<p>Suitable for all skin types</p>\n<p>Peptide-rich cream for delicate eye skin: rebuilds collagen and elastin, smooths lines, and targets dark circles and puffiness.</p>\n<p>Key benefits</p>\n<p>\u2013 Antioxidants to help protect skin cells</p>\n<p>\u2013 Rebuilds for a firmer, fuller look and helps prevent eye wrinkles</p>\n<p>\u2013 Helps protect collagen and elastin</p>\n<p>\u2013 Soothes puffy eye bags</p>\n<p>Key ingredients</p>\n<p>\u2013 Cyclic tetrapeptide</p>\n<p>\u2013 Hexapeptide</p>\n<p>\u2013 Pentapeptide acid</p>\n<p>\u2013 Palmitoyl tetrapeptide</p>\n<p>\u2013 Oxidoreductase</p>\n<p>\u2013 Sodium hyaluronate</p>","price_hkd":850,"stock":20,"image_paths":["/images/products/prod-5@2x.jpg"],"sort":225}]$json$::jsonb) as x(
  brand_slug text, slug text, title_zh_hk text, title_zh_cn text, title_en text,
  description_zh_hk text, description_zh_cn text, description_en text,
  price_hkd numeric, stock int, image_paths jsonb, sort int
)
join public.brands b on b.slug = x.brand_slug;